import asyncio
from sc2 import maps, run_game, Race, Difficulty
from sc2.player import Bot, Computer
from sc2.bot_ai import BotAI
from sc2.ids.unit_typeid import UnitTypeId
from sc2.ids.ability_id import AbilityId
from sc2.ids.upgrade_id import UpgradeId
from sc2.position import Point2
from sc2.data import Result

class ZergRushBot(BotAI):
    async def on_start(self):
        await self.client.chat_send("GL HF! Zerg Rush incoming!", team_only=False)
        await self.client.game_step(2)
        self.rush_started = False

    async def on_step(self, iteration):
        # Send a chat message at the start of the rush
        if not self.rush_started and self.supply_used >= 14:
            await self.client.chat_send("Zerg Rush!", team_only=False)
            self.rush_started = True

        await self.inject_larva()
        await self.manage_resources()
        await self.research_upgrades()
        await self.train_units()
        await self.build_structures()
        await self.attack_enemy()
        await self.draw_creep_pixelmap()

    async def on_end(self, game_result: Result):
        print(f"Game ended with result: {game_result}")

    async def inject_larva(self):
        for queen in self.units(UnitTypeId.QUEEN).idle:
            abilities = await self.get_available_abilities(queen)
            if AbilityId.EFFECT_INJECTLARVA in abilities:
                hatch = self.townhalls.ready.random_or(None)
                if hatch:
                    queen(AbilityId.EFFECT_INJECTLARVA, hatch)

    async def manage_resources(self):
        # Extractor trick: build extractor if we have 12 drones and no extractor
        if self.supply_used >= 12 and self.structures(UnitTypeId.EXTRACTOR).amount < 1:
            if self.can_afford(UnitTypeId.EXTRACTOR):
                drone = self.workers.random_or(None)
                vespene = self.vespene_geyser.closer_than(10, self.start_location).random_or(None)
                if drone and vespene:
                    drone.build(UnitTypeId.EXTRACTOR, vespene)
        # Assign workers to gas
        for extractor in self.structures(UnitTypeId.EXTRACTOR).ready:
            if extractor.assigned_harvesters < extractor.ideal_harvesters:
                drone = self.workers.idle.random_or(None)
                if drone:
                    drone.gather(extractor)

    async def research_upgrades(self):
        # Research Zergling Speed
        if self.structures(UnitTypeId.SPAWNINGPOOL).ready and self.can_afford(UpgradeId.ZERGLINGMOVEMENTSPEED):
            pool = self.structures(UnitTypeId.SPAWNINGPOOL).ready.first
            abilities = await self.get_available_abilities(pool)
            if AbilityId.RESEARCH_ZERGLINGMETABOLICBOOST in abilities:
                pool(AbilityId.RESEARCH_ZERGLINGMETABOLICBOOST)

    async def train_units(self):
        # Train Zerglings
        for hatch in self.townhalls.ready.idle:
            if self.can_afford(UnitTypeId.ZERGLING) and self.supply_left >= 2:
                hatch.train(UnitTypeId.ZERGLING)
        # Train Overlords if supply is low
        if self.supply_left < 2 and self.can_afford(UnitTypeId.OVERLORD):
            hatch = self.townhalls.ready.random_or(None)
            if hatch:
                hatch.train(UnitTypeId.OVERLORD)
        # Train Queens if we have a Spawning Pool and less than 2 Queens
        if self.structures(UnitTypeId.SPAWNINGPOOL).ready and self.units(UnitTypeId.QUEEN).amount < 2:
            for hatch in self.townhalls.ready.idle:
                if self.can_afford(UnitTypeId.QUEEN):
                    hatch.train(UnitTypeId.QUEEN)

    async def build_structures(self):
        # Build Spawning Pool if we don't have one
        if self.structures(UnitTypeId.SPAWNINGPOOL).amount < 1 and self.can_afford(UnitTypeId.SPAWNINGPOOL):
            drone = self.workers.random_or(None)
            if drone:
                pos = await self.get_build_location(UnitTypeId.SPAWNINGPOOL)
                if pos:
                    drone.build(UnitTypeId.SPAWNINGPOOL, pos)
        # Build Overlord if supply is low (handled in train_units)
        # Build Extractor (handled in manage_resources)

    async def get_build_location(self, building_type):
        # Find a buildable location near the main hatchery
        hatch = self.townhalls.ready.random_or(None)
        if hatch:
            for _ in range(10):
                pos = hatch.position.towards(self.game_info.map_center, 5).random_on_distance(3)
                if await self.can_place(building_type, pos):
                    return pos
        return None

    async def attack_enemy(self):
        # Attack enemy structures with all Zerglings
        if self.units(UnitTypeId.ZERGLING).amount > 10:
            targets = self.enemy_structures
            if targets:
                target = targets.closest_to(self.start_location)
                for zergling in self.units(UnitTypeId.ZERGLING).idle:
                    zergling.attack(target.position)
            else:
                # If no structures, attack enemy start location
                for zergling in self.units(UnitTypeId.ZERGLING).idle:
                    zergling.attack(self.enemy_start_locations[0])

    async def draw_creep_pixelmap(self):
        # Draw creep as purple pixels for debugging
        for x in range(0, self.game_info.map_size.width, 4):
            for y in range(0, self.game_info.map_size.height, 4):
                pos = Point2((x, y))
                if self.state.creep_cover_map.is_set(pos):
                    self._client.debug_text_world("C", pos, size=8, color=(128, 0, 128))

if __name__ == "__main__":
    asyncio.get_event_loop().run_until_complete(
        run_game(
            maps.get("AcropolisLE"),
            [
                Bot(Race.Zerg, ZergRushBot()),
                Computer(Race.Terran, Difficulty.Medium)
            ],
            realtime=False,
            save_replay_as="zerg_rush_bot.SC2Replay"
        )
    )
